  if (s >= p.flag) return { route: "escalate", reason: `signal=${s.toFixed(2)} in [${p.flag},${p.act})` };
  const route: Route = p.fail === "closed" ? "reject" : "noop";
  return { route, reason: `signal=${s.toFixed(2)} < flag=${p.flag}, fail=${p.fail}` };
}

