  const rows = this.db.query("SELECT state, COUNT(*) AS n FROM queue GROUP BY state").all() as { state: string; n: number }[];
  const m = new Map(rows.map(r => [r.state, r.n]));
  const pending = m.get("pending") ?? 0, running = m.get("running") ?? 0,
        done = m.get("done") ?? 0, failed = m.get("failed") ?? 0;
  return { pending, running, done, failed, total: pending + running + done + failed };
}

