export function readLedger(): LedgerRow[] {
  const p = ledgerPath();
  if (!existsSync(p)) return [];
  return readFileSync(p, "utf8")
    .split("\n").filter(Boolean)
    .map((l): LedgerRow | null => {
      try {
        const obj = JSON.parse(l);
        if (!isLedgerRow(obj)) { console.error(`JM_LEDGER: dropping non-conformant row in ${p}`); return null; }
        return obj;
      } catch {
        console.error(`JM_LEDGER: dropping unparseable line in ${p}`);
        return null;
      }
    })
    .filter((r): r is LedgerRow => r !== null);
}

function isLedgerRow(obj: unknown): obj is LedgerRow {
  if (typeof obj !== "object" || obj === null) return false;
  const r = obj as Record<string, unknown>;
  return r.kind === "run"
    && typeof r.ts === "string" && typeof r.verb === "string"
    && typeof r.started === "string" && typeof r.ended === "string"
    && (r.status === "ok" || r.status === "error")
    && typeof r.cost_usd === "number" && typeof r.calls === "number" && typeof r.cached === "number";
}

